INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c8f3-7aaf-aa86-7fce1777f966'::uuid, '019f9df7-a2a2-7930-a717-cd252273c91f'::uuid, 'A bar chart compares monthly sales, but its vertical axis begins at $1500 instead of $0. Explain how this could mislead readers.', 'It exaggerates visible bar differences, making small variations appear much larger.', 'Starting the vertical axis above zero removes the baseline and exaggerates the visible heights of the bars. Readers may therefore overestimate the differences between months.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.115Z'::timestamptz, '2026-08-15T07:50:40.115Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c911-7720-9bd3-e464de4c4e5e'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Express 360 as a product of its prime factors.', '2³ × 3² × 5', '360 = 36 × 10 = (2² × 3²)(2 × 5) = 2³ × 3² × 5.', 'Easy', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.145Z'::timestamptz, '2026-08-15T07:50:40.145Z'::timestamptz) ON CONFLICT (id) DO NOTHING;
INSERT INTO bridging.questions (id, topic_id, prompt, model_answer, explanation, difficulty, metadata, diagram_path, question_type, answer_tolerance, accepted_answers, case_sensitive, require_simplified_form, require_units, required_unit, accepted_units, marking_notes, syntax_migration_status, syntax_migration_notes, created_at, updated_at) VALUES ('01a00466-c91b-7e98-af40-d3a0a6c9daf3'::uuid, '019f9df7-a2a0-71cf-9863-4d6d67e42e6d'::uuid, 'Two integers have HCF 18 and LCM 360. Both integers are greater than 40. Find the two integers.', '72 and 90', 'Let the numbers be 18a and 18b, where a and b are coprime. Since their product is HCF × LCM = 18 × 360, ab = 20. The coprime factor pair giving numbers > 40 is a = 4 and b = 5, giving 72 and 90.', 'Medium', '{"diagram_required":false}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-15T07:50:40.155Z'::timestamptz, '2026-08-15T07:50:40.155Z'::timestamptz) ON CONFLICT (id) DO NOTHING;